with base as (select id, name, email, city, segment, signup_date, is_active, credit_limit, round(credit_limit * 1.1, 2) as credit_limit_adjusted, upper(segment) as segment_upper from customers where signup_date > date '2023-03-06' and city is not null) select * from (select *, row_number() over (partition by city, segment order by credit_limit, id) as rn from base) x where rn = 1;
